create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_DIM_BUSINESS_HALF_YEAR_1 (
	BUS_HALF_YEAR NUMBER(38,0) NOT NULL COMMENT 'The identifier for a business half year in the form YYYYn. The first half year in the Lidl business year is from March to August, the second half year from September to February. E.g. 20211 for the first half of  the business year 2021.',
	BUS_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business year as a number in the form YYYY. Eg. 2019',
	BUS_HALF_YEAR_NAME VARCHAR(100) NOT NULL COMMENT 'The text which is displayed for the business half year in reports, in group language, i.e. German. E.g. 2021-HJ1 for the first half of the business year 2021.',
	BUS_HALF_YEAR_NAME_DE VARCHAR(100) COMMENT 'The text which is displayed for the business half year in reports, in German. E.g. 2021-HJ1 for the first half of the business year 2021.',
	BUS_HALF_YEAR_NAME_EN VARCHAR(100) COMMENT 'The text which is displayed for the business half year in reports, in English. E.g. 2021-HY1 for the first half of the business year 2021.',
	HALF_OF_BUS_YEAR NUMBER(38,0) COMMENT 'The number of the half year within the business year. E.g. 1 for the first half year of 2021.',
	BUS_HALF_YEAR_BEGIN_MONTH NUMBER(38,0) NOT NULL COMMENT 'The first (calendar_1) month (inclusive) of the business half year as a number in the form YYYYMM. Eg. 201901.',
	BUS_HALF_YEAR_END_MONTH NUMBER(38,0) NOT NULL COMMENT 'The last (calendar_1) month (inclusive) of the business half year as a number in the form YYYYMM. Eg. 201912.',
	BUS_HALF_YEAR_BEGIN_PART_WEEK NUMBER(38,0) NOT NULL COMMENT 'The first partial week (inclusive) of the business half year as a number in the form YYYYWWn. Eg. 2019012.',
	BUS_HALF_YEAR_END_PART_WEEK NUMBER(38,0) NOT NULL COMMENT 'The last partial week (inclusive) of the business half year as a number in the form YYYYWWn. Eg. 2020011.',
	BUS_HALF_YEAR_BEGIN_DT DATE NOT NULL COMMENT 'The first day (inclusive) of the business half year as a conventional calendar_1 date in the form ''YYYY-MM_1-DD''. Eg. ''2019-01-01''.',
	BUS_HALF_YEAR_END_DT DATE NOT NULL COMMENT 'The first day (inclusive) of the business half year as a conventional calendar_1 date in the form ''YYYY-MM_1-DD''. Eg. ''2019-12-31''. ',
	BUS_HALF_YEAR_WEEK_CNT NUMBER(38,0) COMMENT 'The number of weeks that this business half year contains. If a week spans two business half years, it is counted for the half year, in which it has at least four days.',
	BUS_HALF_YEAR_PART_WEEK_CNT NUMBER(38,0) COMMENT 'The number of partial weeks that this business half year contains.',
	BUS_HALF_YEAR_DAY_CNT NUMBER(38,0) COMMENT 'The number of days that this business half year contains.',
	PREV_1Y_BUS_HALF_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business half year one year ago as a number in the form YYYYn. Eg. 20201, if the current half year is 20211.',
	PREV_2Y_BUS_HALF_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business half year two years ago as a number in the form YYYYn. Eg. 20191, if the current half year is 20211.',
	PREV_3Y_BUS_HALF_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business half year three years ago as a number in the form YYYYn. Eg. 20181, if the current half year is 20211.',
	PREV_4Y_BUS_HALF_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business half year four years ago as a number in the form YYYYn. Eg. 20171, if the current half year is 20211.',
	PREV_5Y_BUS_HALF_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business half year five years ago as a number in the form YYYYn. Eg. 20161, if the current half year is 20211.',
	CURR_BUS_HALF_YEAR_FG BOOLEAN NOT NULL COMMENT 'This indicator is set for the current business half year.',
	BUS_HALF_YEAR_OFFSET NUMBER(38,0) COMMENT 'The difference in business half years between this business half year and the current business half year. So if the current half year is 20211 then the offset is 0 for 20211, -1 for 20202 and +1 for 20212.',
	BUS_YEAR_OFFSET NUMBER(38,0) COMMENT 'The difference in years between the business year to which this business half year belongs, and the current business year. So if the current business year is 2019, then the offset is 0 for 2019, -1 for 2018 and +1 for 2020.  ',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_BUSINESS_HALF_YEAR primary key (BUS_HALF_YEAR)
)COMMENT='A half of a business year. The first half year in the Lidl business year is from March to August, the second half year from September to February. E.g. 20211 for the first half of  the business year 2021.'
;